/**
 * Friend Requests API 测试
 */

import { SynapseEnhancedClient } from "../index.ts";
import { loadTestConfig } from "./config.ts";
import { logger } from "../../logger.ts";

const log = logger.getChild("enhanced:test:friend-requests-api");

interface TestResult {
    name: string;
    passed: boolean;
    responseTime: number;
    error?: string;
    response?: any;
}

export class FriendRequestsApiTests {
    private client: SynapseEnhancedClient;
    private config: ReturnType<typeof loadTestConfig>;

    public constructor() {
        this.config = loadTestConfig();
        this.client = new SynapseEnhancedClient({
            baseUrl: this.config.server.baseUrl,
            accessToken: this.config.server.accessToken,
            apiPrefix: this.config.server.apiPrefix,
            timeout: this.config.test.timeout,
        });
    }

    public async runAllTests(): Promise<TestResult[]> {
        log.info("");
        log.info("=============================");
        log.info("Running Friend Requests API Tests...");
        log.info("=============================");

        const results: TestResult[] = [];

        results.push(await this.testGetReceivedRequests());
        results.push(await this.testGetSentRequests());

        this.printResults(results);
        return results;
    }

    private printResults(results: TestResult[]): void {
        for (const result of results) {
            const icon = result.passed ? "✓" : "✗";
            log.info(`${icon} ${result.name}: ${result.passed ? "PASSED" : "FAILED"} (${result.responseTime}ms)`);
            if (result.error) {
                log.error(`  Error: ${result.error}`);
            }
        }
        const passed = results.filter((r) => r.passed).length;
        log.info("");
        log.info(`Friend Requests API Results: ${passed}/${results.length} passed`);
    }

    private async testGetReceivedRequests(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const requests = await this.client.friends.getReceivedRequests();

            return {
                name: "Get Received Requests",
                passed: Array.isArray(requests),
                responseTime: Date.now() - startTime,
                response: { count: requests.length },
            };
        } catch (error: any) {
            return {
                name: "Get Received Requests",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }

    private async testGetSentRequests(): Promise<TestResult> {
        const startTime = Date.now();
        try {
            const requests = await this.client.friends.getSentRequests({ page: 1, limit: 10 });

            return {
                name: "Get Sent Requests",
                passed: Array.isArray(requests),
                responseTime: Date.now() - startTime,
                response: { count: requests.length },
            };
        } catch (error: any) {
            return {
                name: "Get Sent Requests",
                passed: false,
                responseTime: Date.now() - startTime,
                error: error.message,
            };
        }
    }
}

const tests = new FriendRequestsApiTests();
tests.runAllTests().catch((error) => log.error(error));
